let db;try{db=JSON.parse(localStorage.getItem('verdant-v1'));if(!db||db.version!==1)db=seed()}catch{db=seed()}
let page='Overview',filter='',statusFilter='All',countryFilter='All',categoryFilter='All',reqTab='All requirements',selectedGroup='g1',globalQuery='',currentPage=1;
const save=()=>localStorage.setItem('verdant-v1',JSON.stringify(db));
const log=(title,detail,type='bolt')=>{db.activity.unshift({title,detail,type,time:'Just now'});db.activity=db.activity.slice(0,40);save()};
const initials=n=>n.split(' ').slice(0,2).map(x=>x[0]).join('');
const flag=c=>({'France':'🇫🇷','United Kingdom':'🇬🇧','Germany':'🇩🇪','Netherlands':'🇳🇱','Spain':'🇪🇸'}[c]||'🌍');
const color=c=>({'Technology':'','Healthcare':'purple','Hospitality':'orange','Logistics':'green','Design':'purple'}[c]||'green');
const pill=s=>`<span class="pill ${['Matching','Pending review','Draft'].includes(s)?'amber':['Outreach','Sent','In progress'].includes(s)?'blue':['Filled','Done','Replied'].includes(s)?'':'Open'===s?'':'gray'}">${s==='Open'?'<span class="dot"></span>':''}${esc(s)}</span>`;
function matches(r){const terms=r.skills.toLowerCase().split(',').map(x=>x.trim()).filter(Boolean);return db.leads.filter(l=>!l.blocked&&l.availability!=='Unavailable'&&l.country.toLowerCase()===r.country.toLowerCase()&&l.category.toLowerCase()===r.category.toLowerCase()).map(l=>({...l,score:Math.min(99,65+(l.city.toLowerCase()===r.city.toLowerCase()?20:0)+Math.round(terms.filter(t=>l.skills.toLowerCase().includes(t)).length/Math.max(1,terms.length)*14))})).sort((a,b)=>b.score-a.score)}
const btn=(text,action,primary=false,icon='')=>`<button type="button" class="btn ${primary?'primary':''}" data-action="${action}">${icon?ic(icon):''}${text}</button>`;
const navItems=[['Overview','grid'],['Requirements','brief'],['Lead database','users'],['WhatsApp inbox','chat'],['Outreach','send'],['Tasks & pipeline','tasks'],['Reports','chart']];
function render(){document.getElementById('app').innerHTML=`<div class="layout"><aside class="sidebar"><a href="#" class="brand" data-nav="Overview"><span class="brandmark">${ic('leaf')}</span>verdant<span style="font-size:13px;color:#a7b3a9">®</span></a><div class="workspace"><span class="avatar">VT</span><div><strong>${esc(db.settings.workspace)}</strong><small>Talent workspace</small></div>${ic('down')}</div><div class="nav-label">WORKSPACE</div><nav class="nav">${navItems.map(([n,i])=>`<button data-nav="${n}" class="${page===n?'active':''}">${ic(i)}${n}${n==='Requirements'?`<span class="count">${db.requirements.filter(r=>r.status!=='Filled').length}</span>`:''}${n==='WhatsApp inbox'?'<span class="count">5</span>':''}</button>`).join('')}</nav><div class="nav-label" style="margin-top:30px">MANAGE</div><nav class="nav"><button data-nav="Automation" class="${page==='Automation'?'active':''}">${ic('bolt')}Automation</button><button data-nav="Settings" class="${page==='Settings'?'active':''}">${ic('settings')}Settings</button></nav><div class="sidebar-bottom"><div class="help-card"><h3>${ic('spark')} A little less busywork.</h3><p>Your next great hire starts with a better workflow.</p><button data-action="guide">Explore your workspace →</button></div><button class="profile" data-nav="Settings"><span class="avatar" style="background:#f1e8dc;color:#a18b69">AM</span><div style="text-align:left"><strong>Alex Morgan</strong><small>Workspace admin</small></div>${ic('down')}</button></div></aside><main class="main"><header class="topbar"><div class="mobile-brand"><button class="icon-btn menu-toggle" data-action="menu" aria-label="Open navigation">${ic('menu')}</button>verdant</div><div class="crumb">Workspace<span>/</span><strong>${page}</strong></div><div class="top-tools"><label class="search">${ic('search')}<input id="global-search" placeholder="Search anything..." aria-label="Search all records" value="${esc(globalQuery)}"><span class="key">↵</span></label><span class="demo-badge">Demo workspace</span><button class="icon-btn" aria-label="View activity" data-action="notifications">${ic('bell')}</button><span class="avatar" style="width:29px;height:29px;font-size:9px">AM</span></div></header><div class="content">${heading()}${content()}<footer class="footnote"><span>Thoughtfully connected. Effortlessly organized.</span><span><span class="dot"></span> Browser-local demo · All changes saved on this device</span></footer></div></main></div>`;bind()}
function heading(){const subtitles={'Overview':'Here’s what’s happening across your talent network today.','Requirements':'Every opportunity, organized. From first message to the perfect match.','Lead database':'The right people, ready for the right opportunity.','WhatsApp inbox':'Turn conversations into clear, actionable requirements.','Outreach':'A clear view of every conversation you start.','Tasks & pipeline':'Keep your team aligned and every opportunity moving.','Reports':'A little perspective on your recruiting momentum.','Automation':'Your workflow, working thoughtfully in the background.','Settings':'Make this workspace work for you.'};return `<div class="heading"><div><h1>${page==='Overview'?'Good morning, Alex <span style="font-size:23px;color:#d4ac65">☀</span>':page}</h1><p>${subtitles[page]}</p></div><div class="actions">${page==='Overview'?`<span class="live-label"><span class="dot"></span> Workspace is up to date</span>${btn('New requirement','new-req',true,'plus')}`:page==='Requirements'?btn('New requirement','new-req',true,'plus'):page==='Lead database'?btn('Import leads','import',false,'upload')+btn('Add lead','new-lead',true,'plus'):page==='WhatsApp inbox'?btn('Simulate message','simulate',true,'plus'):page==='Tasks & pipeline'?btn('Create task','new-task',true,'plus'):page==='Reports'?btn('Export report','export-report',false,'download'):''}</div></div>`}
function statCards(){const active=db.requirements.filter(r=>r.status!=='Filled').length,eligible=db.leads.filter(l=>l.consent&&!l.blocked).length,sent=db.outreach.filter(o=>['Sent','Replied'].includes(o.status)).length;return `<div class="overview-grid">${[['Active requirements',active,'brief','Across '+db.groups.length+' demo groups'],['Talent in your network',db.leads.length,'users',eligible+' opted in to outreach'],['Messages sent',sent,'send','Simulated outreach messages'],['Successful matches',db.outreach.filter(o=>o.status==='Replied').length,'check','Candidates who responded']].map(([t,v,i,d])=>`<div class="stat"><div class="stat-top">${t}<span class="stat-icon">${ic(i)}</span></div><div class="stat-value">${String(v).padStart(2,'0')}</div><div class="stat-bottom"><span class="trend">${ic('arrow').replace('<svg','<svg style="width:10px;height:10px;transform:rotate(-40deg)"')}</span>${d}</div></div>`).join('')}</div>`}
function requirementTable(rows,overview=false){return `<div class="table-wrap"><table><thead><tr><th>Requirement</th><th>Location</th><th>Matches</th><th>Status</th><th></th></tr></thead><tbody>${rows.map(r=>`<tr class="click-row" data-detail="${r.id}" tabindex="0" role="button" aria-label="Open ${esc(r.role)}"><td><div class="role-cell"><span class="role-icon ${color(r.category)}">${ic(r.category==='Healthcare'?'shield':r.category==='Design'?'spark':'brief')}</span><div><strong>${esc(r.role)}</strong><small>${esc(r.category)} <span style="margin:0 4px">·</span> ${r.count} position${r.count>1?'s':''}</small></div></div></td><td><span class="country">${flag(r.country)} ${esc(r.city)}</span><small>${esc(r.country)}</small></td><td><span class="match">${matches(r).length} profiles</span></td><td>${pill(r.status)}</td><td><button class="icon-btn" data-action="detail:${r.id}" aria-label="Open requirement">${ic('arrow')}</button></td></tr>`).join('')||'<tr><td colspan="5" class="empty">No requirements match your filters.</td></tr>'}</tbody></table></div>`}
function activityCard(limit=4){return `<div class="card"><div class="card-head"><h2>Activity feed</h2><span class="live-label"><span class="dot"></span> Live demo</span></div><div class="activity">${db.activity.slice(0,limit).map(a=>`<div class="event"><span class="event-icon">${ic(a.type)}</span><div><strong>${esc(a.title)}</strong><p>${esc(a.detail)}</p><small>${esc(a.time)}</small></div></div>`).join('')}</div><div class="table-footer"><button class="text-btn" data-action="notifications">View all activity ${ic('arrow')}</button></div></div>`}
function engine(){return `<div class="engine"><div class="engine-title">${ic('bolt')}<h3>Your matching copilot</h3><span class="engine-state"><span class="dot"></span>${db.settings.auto?'Auto':'Ready'}</span></div><p>From a group message to the right person.<br>A smarter workflow, with you in control.</p><div class="engine-steps"><span class="engine-step">${ic('chat')}Capture</span><span class="engine-step">${ic('users')}Match</span><span class="engine-step">${ic('send')}Connect</span></div>${btn('Run demo automation','run-engine',false,'bolt')}</div>`}
function chart(){const days=['Mon','Tue','Wed','Thu','Fri','Sat','Sun'];const values=days.map((_,i)=>i===0?db.outreach.length:0);const max=Math.max(...values,1);return `<div class="card"><div class="card-head"><div><h2>Outreach overview</h2><p>Messages created in this demo session</p></div><span class="pill gray">This week</span></div><div class="bar-chart">${days.map((d,i)=>`<div class="bar-item"><div class="bar" title="${d}: ${values[i]}" style="height:${Math.max(3,values[i]/max*100)}px"></div><span>${d}</span></div>`).join('')}</div><div class="chart-label"><span class="dot"></span> ${db.outreach.length} messages · ${db.outreach.filter(o=>o.status==='Draft').length} awaiting review</div></div>`}
function overview(){const rows=db.requirements.filter(r=>reqTab==='All requirements'||(reqTab==='Open'?r.status==='Open':r.status==='Filled'));return `${statCards()}<div class="dashboard-grid"><div><div class="card"><div class="card-head"><div><h2>Recent requirements</h2><p>Fresh opportunities from your connected groups</p></div><button class="text-btn" data-nav="Requirements">View all ${ic('arrow')}</button></div><div class="tabs">${['All requirements','Open','Filled'].map(t=>`<button class="${reqTab===t?'active':''}" data-tab="${t}">${t}${t==='All requirements'?`<span>${db.requirements.length}</span>`:''}</button>`).join('')}</div>${requirementTable(rows.slice(0,5),true)}<div class="table-footer"><span>Showing ${Math.min(rows.length,5)} of ${rows.length} requirements</span><button class="text-btn" data-nav="Requirements">Manage requirements ${ic('arrow')}</button></div></div><div class="bottom-grid section-space">${chart()}<div class="card"><div class="card-head"><div><h2>Connected groups</h2><p>Your opportunity network</p></div><button class="text-btn" data-nav="WhatsApp inbox">${ic('arrow')}</button></div><div class="groups-list">${db.groups.slice(0,3).map(g=>`<button class="group-row" style="width:100%;text-align:left" data-group="${g.id}"><span class="group-icon">${ic('users')}</span><div><strong>${esc(g.name)}</strong><small>${g.members} members · ${esc(g.country)}</small></div><span class="pill">Active</span></button>`).join('')}</div></div></div></div><div class="right-column">${engine()}${activityCard()}</div></div>`}
function toolbar(lead=false){return `<div class="toolbar"><label class="search" style="flex:1">${ic('search')}<input id="filter" placeholder="${lead?'Search people, skills, city...':'Search requirements, roles, groups...'}" value="${esc(filter)}" aria-label="Search records"></label><select id="country-filter" aria-label="Filter country"><option value="All">All countries</option>${[...new Set([...db.leads,...db.requirements].map(x=>x.country))].map(x=>`<option ${x===countryFilter?'selected':''}>${esc(x)}</option>`).join('')}</select><select id="category-filter" aria-label="Filter category"><option value="All">All categories</option>${[...new Set([...db.leads,...db.requirements].map(x=>x.category))].map(x=>`<option ${x===categoryFilter?'selected':''}>${esc(x)}</option>`).join('')}</select>${!lead?`<select id="status-filter" aria-label="Filter status">${['All','Open','Matching','Outreach','Filled'].map(x=>`<option ${x===statusFilter?'selected':''} value="${x}">${x==='All'?'All statuses':x}</option>`).join('')}</select>`:btn('Export CSV','export-leads',false,'download')}</div>`}
function filtered(items){return items.filter(x=>(countryFilter==='All'||x.country===countryFilter)&&(categoryFilter==='All'||x.category===categoryFilter)&&(!filter||Object.values(x).join(' ').toLowerCase().includes(filter.toLowerCase())))}
function leadTable(rows){return `<div class="table-wrap"><table><thead><tr><th>Candidate</th><th>Location</th><th>Expertise</th><th>Availability</th><th>Outreach consent</th><th></th></tr></thead><tbody>${rows.map(l=>`<tr><td><div class="role-cell"><span class="avatar">${initials(l.name)}</span><div><strong>${esc(l.name)}</strong><small>${esc(l.id)} · ${esc(l.email)}</small></div></div></td><td>${flag(l.country)} ${esc(l.city)}<small>${esc(l.country)}</small></td><td>${esc(l.category)}<small>${esc(l.skills)}</small></td><td>${pill(l.availability)}</td><td><span class="pill ${l.blocked?'red':l.consent?'':'amber'}">${l.blocked?'Excluded':l.consent?'Opted in':'Not opted in'}</span></td><td><button class="text-btn" data-action="edit-lead:${l.id}">View profile ${ic('arrow')}</button></td></tr>`).join('')||'<tr><td colspan="6" class="empty">No candidates found. Try changing your filters.</td></tr>'}</tbody></table></div>`}
function inbox(){let g=db.groups.find(g=>g.id===selectedGroup)||db.groups[0];return `<div class="notice">${ic('shield')}Demo inbox: messages and voice transcripts are simulated. Real group ingestion requires a supported integration.</div><div class="card inbox"><div class="chat-list"><h3>Your groups <small>(${db.groups.length})</small></h3>${db.groups.map(x=>`<button class="chat-item ${g.id===x.id?'selected':''}" data-group="${x.id}"><span class="avatar">${flag(x.country)}</span><div><strong>${esc(x.name)}</strong><p>${x.members} members · ${x.active?'Monitoring':'Paused'}</p></div></button>`).join('')}</div><div class="chat-panel"><div class="chat-head"><div><strong>${esc(g.name)}</strong><small style="display:block;margin-top:5px;font-size:10px">${esc(g.category)} · ${esc(g.country)}</small></div><button class="btn" data-action="toggle-group:${g.id}">${ic(g.active?'clock':'play')}${g.active?'Pause capture':'Resume capture'}</button></div><div class="messages">${db.messages.filter(m=>m.group===g.id).map(m=>`<div class="bubble ${m.sender==='You'?'out':''}"><strong style="font-size:10px;color:#47845f">${esc(m.sender)}</strong>${m.kind==='voice'?`<div class="voice" style="margin-top:10px"><button class="icon-btn" data-action="voice:${m.id}" aria-label="Play demo voice note">${ic('play')}</button><div class="wave">${Array.from({length:32},(_,i)=>`<i style="height:${7+(i*17%23)}px"></i>`).join('')}</div><span style="font-size:9px">0:18</span></div><div class="transcript">Demo transcript: ${esc(m.text)}</div>`:`<p>${esc(m.text)}</p>`}<small>${esc(m.time)} ${m.processed?` · <button class="text-btn" style="display:inline;font-size:9px" data-action="detail:${m.req}">Requirement captured ↗</button>`:m.sender!=='You'?` · <button class="text-btn" style="display:inline;font-size:9px" data-action="extract:${m.id}">Review & capture →</button>`:' · Demo message'}</small></div>`).join('')||'<div class="empty">No messages yet. Simulate a group message to get started.</div>'}</div><form class="chat-compose" id="chat-form"><input name="message" required placeholder="Write a simulated reply to this group…" aria-label="Demo reply"><button class="btn primary" type="submit">${ic('send')}Send demo</button></form></div></div>`}
function outreach(){const rows=db.outreach.filter(o=>statusFilter==='All'||o.status===statusFilter);return `<div class="notice">${ic('shield')}Demo delivery only. Excluded candidates and contacts without outreach consent cannot be sent messages.</div><div class="toolbar"><div class="tabs" style="padding:0;flex:1">${['All','Draft','Sent','Replied','Skipped'].map(s=>`<button data-outreach-tab="${s}" class="${statusFilter===s?'active':''}">${s==='All'?'All messages':s}<span>${s==='All'?db.outreach.length:db.outreach.filter(o=>o.status===s).length}</span></button>`).join('')}</div>${btn('Run matching','run-engine',true,'bolt')}</div>${rows.map(o=>{const l=db.leads.find(l=>l.id===o.lead),r=db.requirements.find(r=>r.id===o.req);return `<div class="card campaign"><div class="campaign-top"><div class="role-cell"><span class="avatar">${initials(l?.name||'Unknown')}</span><div><h3>${esc(l?.name||'Unknown candidate')}</h3><small style="font-size:10px">${esc(r?.role||'')} · ${esc(l?.city||'')}</small></div></div>${pill(o.status)}</div><p>${esc(o.text)}</p><div class="campaign-bottom"><span class="muted" style="font-size:10px">${esc(o.time)} · ${esc(o.req)} · ${l?.consent?'Opted-in contact':'No outreach consent'}</span><div class="actions">${o.status==='Draft'?btn('Skip','skip:'+o.id)+btn('Edit draft','edit-outreach:'+o.id)+btn('Approve & simulate send','send:'+o.id,true,'send'):o.status==='Sent'?btn('Simulate reply','reply:'+o.id,false,'chat'):o.status==='Replied'?'<span class="pill">Ready for follow-up</span>':''}</div></div></div>`}).join('')||'<div class="card empty">No messages in this queue.</div>'}`}
function tasks(){return `<div class="board">${['To do','In progress','Done'].map(s=>`<section class="column"><h3>${s}<span class="pill gray">${db.tasks.filter(t=>t.status===s).length}</span></h3>${db.tasks.filter(t=>t.status===s).map(t=>`<div class="task-card"><span class="mini-label">${esc(t.req||'WORKSPACE')}</span><h3 style="margin-top:9px">${esc(t.title)}</h3><p>${esc(t.description)}</p><div class="actions">${s!=='Done'?btn(s==='To do'?'Start task':'Mark complete','move-task:'+t.id,false,s==='To do'?'arrow':'check'):btn('Reopen','move-task:'+t.id,false,'refresh')}${btn('Edit','edit-task:'+t.id)}</div><div class="task-meta"><span>${esc(t.owner)}</span><span>${ic('clock').replace('<svg','<svg style="width:10px;height:10px"')} ${esc(t.due)}</span></div></div>`).join('')||'<div class="empty">Nothing here yet.</div>'}</section>`).join('')}</div>`}
function reports(){const sent=db.outreach.filter(o=>['Sent','Replied'].includes(o.status)).length,replies=db.outreach.filter(o=>o.status==='Replied').length,rate=sent?Math.round(replies/sent*100):0;return `${statCards()}<div class="report-cards"><div class="card"><div class="card-head"><h2>Response rate</h2></div><div class="ring" style="background:conic-gradient(var(--green) 0 ${rate}%,#ecf2ed ${rate}%)"><strong>${rate}%</strong></div><p class="empty" style="padding:0 20px 24px">${replies} replies from ${sent} simulated sends</p></div>${chart()}<div class="card"><div class="card-head"><h2>Requirements by market</h2></div><div class="groups-list">${[...new Set(db.requirements.map(r=>r.country))].map(c=>`<div class="group-row"><span>${flag(c)}</span><strong>${esc(c)}</strong><span class="pill" style="margin-left:auto">${db.requirements.filter(r=>r.country===c).length} roles</span></div>`).join('')}</div></div></div><div class="section-space">${activityCard(12)}</div>`}
function automation(){return `<div class="settings-grid"><div>${engine()}<div class="card section-space"><div class="card-head"><h2>Workflow rules</h2></div><div class="form-body">${[['1','Capture a requirement','A message or demo voice transcript becomes a structured requirement.'],['2','Find relevant people','Match on country, city, category, skills and availability.'],['3','Respect your exclusions','Skip blocked, unavailable and non-consenting contacts.'],['4','Create a reviewable draft','One outreach draft per candidate and requirement. Duplicates are prevented.'],['5','Keep work moving','Create a shared review task and record every action in the activity log.']].map(([n,t,d])=>`<div class="event"><span class="avatar" style="height:28px;width:28px">${n}</span><div><strong>${t}</strong><p>${d}</p></div></div>`).join('')}</div></div></div><div class="card"><div class="card-head"><h2>Automation preferences</h2></div><div class="form-body">${switchRow('auto','Process new demo requirements','Automatically match and create drafts when a requirement is added.')}${switchRow('review','Require outreach review','When off, eligible drafts are automatically marked sent in this demo.')}${switchRow('notify','Activity notifications','Show feedback when automation completes.')}<div class="notice" style="margin-top:23px">${ic('shield')}This frontend does not send real WhatsApp messages or run background jobs while closed.</div>${btn('Run workflow now','run-engine',true,'bolt')}</div></div></div>`}
function switchRow(key,title,desc){return `<div class="switch-row"><div><h3 style="font-size:12px">${title}</h3><p>${desc}</p></div><button role="switch" aria-checked="${db.settings[key]}" aria-label="${title}" class="switch ${db.settings[key]?'on':''}" data-action="switch:${key}"></button></div>`}
function settings(){return `<div class="settings-grid"><div class="card"><div class="card-head"><h2>Workspace details</h2></div><form class="form-body" id="settings-form"><div class="field"><label for="workspace-name">Workspace name</label><input id="workspace-name" name="workspace" required value="${esc(db.settings.workspace)}" maxlength="60"></div><div class="field"><label>Admin</label><input value="Alex Morgan" readonly></div><div class="field"><label>Workspace mode</label><input value="Frontend demo · Browser-local storage" readonly></div>${btn('Save changes','save-settings',true,'check')}</form></div><div class="card"><div class="card-head"><h2>Your demo data</h2></div><div class="form-body"><p class="muted" style="font-size:12px;line-height:1.9;margin-bottom:20px">Your requirements, leads, drafts and tasks are saved in this browser. Export a backup to keep a copy. All names and contact details in the initial dataset are fictional.</p><div class="actions">${btn('Export backup','backup',false,'download')}${btn('Restore backup','restore',false,'upload')}</div><div class="notice" style="margin-top:23px">${ic('shield')}No credentials or real messaging integrations are connected.</div>${btn('Reset demo workspace','reset',false,'refresh')}</div></div></div>`}
function searchResults(){const q=globalQuery.toLowerCase();return `<div class="notice">${ic('search')}Results for “${esc(globalQuery)}” <button class="text-btn" data-action="clear-search" style="margin-left:auto">Clear search</button></div><div class="card"><div class="card-head"><h2>Requirements</h2></div>${requirementTable(db.requirements.filter(r=>Object.values(r).join(' ').toLowerCase().includes(q)))}</div><div class="card section-space"><div class="card-head"><h2>People</h2></div>${leadTable(db.leads.filter(l=>Object.values(l).join(' ').toLowerCase().includes(q)))}</div>`}
function content(){if(globalQuery)return searchResults();if(page==='Overview')return overview();if(page==='Requirements'){const rows=filtered(db.requirements).filter(r=>statusFilter==='All'||r.status===statusFilter);return toolbar()+`<div class="card">${requirementTable(rows)}<div class="table-footer">${rows.length} requirements · Click a row to review matches</div></div>`}if(page==='Lead database'){const rows=filtered(db.leads);return toolbar(true)+`<div class="notice">${ic('users')}Import your own CSV or add people individually. Outreach eligibility is controlled on each profile.</div><div class="card">${leadTable(rows)}<div class="table-footer">${rows.length} people in this view · ${db.leads.length} total candidates</div></div>`}return ({'WhatsApp inbox':inbox,'Outreach':outreach,'Tasks & pipeline':tasks,'Reports':reports,'Automation':automation,'Settings':settings}[page]||overview)()}
function navigate(n){page=n;filter='';globalQuery='';statusFilter='All';countryFilter='All';categoryFilter='All';render();window.scrollTo(0,0)}
let toastTimer;function toast(t){const el=document.getElementById('toast');el.textContent=t;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),3500)}
function modal(title,body,footer='',wide=false){document.getElementById('modal-root').innerHTML=`<div class="overlay"><section class="modal ${wide?'wide':''}" role="dialog" aria-modal="true" aria-label="${esc(title)}"><div class="modal-head"><h2>${title}</h2><button class="icon-btn" data-action="close" aria-label="Close dialog">${ic('close')}</button></div><div class="modal-body">${body}</div>${footer?`<div class="modal-foot">${footer}</div>`:''}</section></div>`;document.querySelector('.modal input,.modal textarea,.modal button')?.focus();bindModal()}
function closeModal(){document.getElementById('modal-root').innerHTML=''}
function field(label,name,value='',type='text',required=true){return `<div class="field"><label for="f-${name}">${label}</label><input id="f-${name}" name="${name}" type="${type}" value="${esc(value)}" ${required?'required':''}></div>`}
function selectField(label,name,options,value){return `<div class="field"><label for="f-${name}">${label}</label><select id="f-${name}" name="${name}">${options.map(o=>`<option ${o===value?'selected':''}>${esc(o)}</option>`).join('')}</select></div>`}
const countries=['France','United Kingdom','Germany','Netherlands','Spain'];const categories=['Technology','Healthcare','Hospitality','Logistics','Design','Customer Support','Other'];
function requirementForm(r={},source){modal(r.id?'Edit requirement':'Create a requirement',`<form id="req-form"><div id="form-error" class="field-error"></div>${source?`<div class="notice">${ic('spark')}Review the extracted details before saving. This demo uses simple keyword extraction.</div>`:''}${field('Role / job title','role',r.role)}<div class="form-grid">${field('City','city',r.city||'Paris')}${selectField('Country','country',countries,r.country||'France')}${selectField('Category','category',categories,r.category||'Technology')}${field('Positions','count',r.count||1,'number')}${selectField('Employment type','type',['Full-time','Contract','Part-time'],r.type||'Full-time')}${selectField('Priority','priority',['High','Medium','Low'],r.priority||'Medium')}</div>${field('Required skills (comma separated)','skills',r.skills||'')}${field('Source group','group',r.group||'Manual entry')}<div class="field"><label for="req-desc">Requirement details</label><textarea id="req-desc" name="description" required>${esc(r.description||'')}</textarea></div><button type="submit" class="btn primary">${r.id?'Save changes':'Create requirement'}</button></form>`);document.getElementById('req-form').onsubmit=e=>{e.preventDefault();const d=Object.fromEntries(new FormData(e.target));if(!Number.isInteger(+d.count)||+d.count<1||+d.count>10000){document.getElementById('form-error').textContent='Positions must be a whole number between 1 and 10,000.';return}for(const k of ['role','city','skills','group','description'])if(!d[k].trim()){document.getElementById('form-error').textContent='Please complete all required fields.';return}let item={...r,...d,count:+d.count,id:r.id||'REQ-'+(2401+db.requirements.length),status:r.status||'Open',created:r.created||'Just now',source:r.source||'Manual'};if(r.id)db.requirements=db.requirements.map(x=>x.id===r.id?item:x);else db.requirements.unshift(item);if(source){const m=db.messages.find(x=>x.id===source);m.processed=true;m.req=item.id}log(r.id?'Requirement updated':'Requirement created',item.role+' · '+item.city,'brief');if(db.settings.auto)runEngine(item.id);closeModal();render();toast('Requirement saved'+(db.settings.auto?' · Matching complete':''))}}
function detail(id){const r=db.requirements.find(r=>r.id===id);if(!r)return toast('This message is not linked to a requirement yet.');const list=matches(r);modal(esc(r.role),`<div style="display:flex;justify-content:space-between">${pill(r.status)}<span class="mini-label">${r.id}</span></div><p style="font-size:12px;line-height:1.9;color:#7c8f81;margin-top:16px">${esc(r.description)}</p><div class="detail-grid"><div><small>LOCATION</small><strong>${flag(r.country)} ${esc(r.city)}</strong></div><div><small>POSITIONS</small><strong>${r.count} · ${esc(r.type)}</strong></div><div><small>SOURCE</small><strong>${esc(r.source)}</strong></div><div><small>CATEGORY</small><strong>${esc(r.category)}</strong></div><div><small>PRIORITY</small><strong>${esc(r.priority)}</strong></div><div><small>GROUP</small><strong>${esc(r.group)}</strong></div></div><h3 style="margin:20px 0 8px">Matching people <small>(${list.length})</small></h3><p class="muted" style="font-size:10px;margin-bottom:12px">Based on location, category, skills and availability. Suggested matches require human review.</p>${list.map(l=>`<div class="lead-match"><span class="avatar">${initials(l.name)}</span><div><strong>${esc(l.name)}</strong><small>${esc(l.city)} · ${esc(l.skills)}</small><small>${l.consent?'Opted in':'No outreach consent'} · ${esc(l.availability)}</small></div><span class="match">${l.score}%</span><button class="btn" data-action="edit-lead:${l.id}">Profile</button></div>`).join('')||'<div class="empty">No eligible profiles yet. Import relevant candidates.</div>'}<div class="field" style="margin-top:18px"><label for="req-state">Requirement status</label><select id="req-state">${['Open','Matching','Outreach','Filled'].map(s=>`<option ${s===r.status?'selected':''}>${s}</option>`).join('')}</select></div>`,btn('Edit','edit-req:'+id)+btn('Save status','save-status:'+id)+btn('Create outreach drafts','match:'+id,true,'spark'),true)}
function leadForm(id){const l=db.leads.find(l=>l.id===id)||{};modal(l.id?'Candidate profile':'Add a candidate',`<form id="lead-form"><div class="form-grid">${field('Full name','name',l.name)}${field('Email','email',l.email||'','email',false)}${field('Phone','phone',l.phone||'','text',false)}${field('City','city',l.city||'Paris')}${selectField('Country','country',countries,l.country||'France')}${selectField('Category','category',categories,l.category||'Technology')}</div>${field('Skills (comma separated)','skills',l.skills||'')}${selectField('Availability','availability',['Available','2 weeks','Unavailable'],l.availability||'Available')}<label style="display:block;font-size:12px;margin:18px 0"><input type="checkbox" name="consent" ${l.consent?'checked':''}> Has opted in to opportunity outreach</label><label style="display:block;font-size:12px;margin:18px 0"><input type="checkbox" name="blocked" ${l.blocked?'checked':''}> Exclude from matching and outreach</label><button class="btn primary" type="submit">Save candidate</button></form>`);document.getElementById('lead-form').onsubmit=e=>{e.preventDefault();const d=Object.fromEntries(new FormData(e.target));if(!d.name.trim()||!d.city.trim()||!d.skills.trim())return toast('Name, city and skills are required.');const item={...l,...d,id:l.id||'L-'+uid().slice(0,6),consent:!!d.consent,blocked:!!d.blocked};if(l.id)db.leads=db.leads.map(x=>x.id===l.id?item:x);else db.leads.unshift(item);log(l.id?'Candidate updated':'Candidate added',item.name,'users');closeModal();render();toast('Candidate saved')};}
function runEngine(id){let drafts=0,skips=0;const rs=id?db.requirements.filter(r=>r.id===id):db.requirements.filter(r=>r.status!=='Filled');for(const r of rs){const ms=matches(r);for(const l of ms){if(db.outreach.some(o=>o.lead===l.id&&o.req===r.id))continue;const eligible=l.consent&&!l.blocked;db.outreach.unshift({id:uid(),lead:l.id,req:r.id,status:eligible?(db.settings.review?'Draft':'Sent'):'Skipped',text:`Hi ${l.name.split(' ')[0]}, we have a ${r.role} opportunity in ${r.city} (${r.type.toLowerCase()}). Your ${l.category.toLowerCase()} experience looks relevant. Would you like to hear more?`,time:'Just now'});eligible?drafts++:skips++}if(ms.length&&r.status!=='Filled')r.status='Matching';if(!db.tasks.some(t=>t.req===r.id)){db.tasks.unshift({id:uid(),title:'Review '+r.city+' '+r.category.toLowerCase()+' shortlist',req:r.id,description:`Review ${ms.length} matched profiles for ${r.role}.`,status:'To do',owner:'Alex Morgan',due:'Today'})}}log('Matching workflow completed',`${drafts} ${db.settings.review?'drafts created':'demo sends'} · ${skips} skipped · duplicates prevented`,'bolt');return {drafts,skips}}
function taskForm(id){const t=db.tasks.find(t=>t.id===id)||{};modal(t.id?'Edit task':'Create a shared task',`<form id="task-form">${field('Task title','title',t.title)}<div class="field"><label for="task-desc">Description</label><textarea name="description" id="task-desc" required>${esc(t.description||'')}</textarea></div><div class="form-grid">${selectField('Owner','owner',['Alex Morgan','Sarah Chen'],t.owner||'Alex Morgan')}${selectField('Status','status',['To do','In progress','Done'],t.status||'To do')}${field('Due','due',t.due||'Today')}${selectField('Requirement','req',['General',...db.requirements.map(r=>r.id)],t.req||'General')}</div><button class="btn primary" type="submit">Save task</button></form>`);document.getElementById('task-form').onsubmit=e=>{e.preventDefault();const d=Object.fromEntries(new FormData(e.target));const item={...t,...d,id:t.id||uid()};if(t.id)db.tasks=db.tasks.map(x=>x.id===t.id?item:x);else db.tasks.unshift(item);log('Task saved',item.title,'tasks');closeModal();render();toast('Task saved')}}
function parseCSV(text){let rows=[],row=[],value='',quoted=false;for(let i=0;i<text.length;i++){const c=text[i];if(c==='"'){if(quoted&&text[i+1]==='"'){value+='"';i++}else quoted=!quoted}else if(c===','&&!quoted){row.push(value);value=''}else if((c==='\n'||c==='\r')&&!quoted){if(c==='\r'&&text[i+1]==='\n')i++;row.push(value);if(row.some(v=>v.trim()))rows.push(row);row=[];value=''}else value+=c}if(quoted)throw Error('CSV contains an unclosed quoted field.');row.push(value);if(row.some(v=>v.trim()))rows.push(row);return rows}
function download(name,text,type='text/csv'){const url=URL.createObjectURL(new Blob([text],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
const csvCell=v=>'"'+String(v??'').replaceAll('"','""')+'"';
function importModal(){modal('Import your talent database',`<div class="upload-box">${ic('upload')}<h3 style="margin:10px 0">Bring your people into one place</h3><p>Upload a CSV. Required columns: name, city, country, category, skills.<br>Optional: email, phone, availability, consent.</p><input type="file" id="csv-file" accept=".csv,text/csv" aria-label="Upload candidate CSV"></div><div id="import-preview" style="margin-top:18px"></div><button class="text-btn" style="margin-top:18px" data-action="sample-csv">Download CSV template ${ic('download')}</button>`,btn('Cancel','close')+'<button class="btn primary" id="import-confirm" disabled>Import candidates</button>');let candidates=[];document.getElementById('csv-file').onchange=async e=>{const f=e.target.files[0];if(!f)return;if(f.size>5*1024*1024)return toast('Please use a CSV smaller than 5 MB.');try{const rows=parseCSV((await f.text()).replace(/^\uFEFF/,''));const headers=rows.shift().map(h=>h.trim().toLowerCase());const missing=['name','city','country','category','skills'].filter(h=>!headers.includes(h));if(missing.length)throw Error('Missing columns: '+missing.join(', '));let invalid=0,dupes=0;const seen=new Set(db.leads.map(l=>(l.email||l.name+'|'+l.city).toLowerCase()));candidates=rows.map(row=>Object.fromEntries(headers.map((h,i)=>[h,(row[i]||'').trim()]))).filter(d=>{if(!d.name||!d.city||!d.country||!d.category||!d.skills){invalid++;return false}const key=(d.email||d.name+'|'+d.city).toLowerCase();if(seen.has(key)){dupes++;return false}seen.add(key);return true}).map(d=>({...d,id:'L-'+uid().slice(0,7),availability:['Available','2 weeks','Unavailable'].includes(d.availability)?d.availability:'Available',consent:['true','yes','1'].includes((d.consent||'').toLowerCase()),blocked:false}));document.getElementById('import-preview').innerHTML=`<div class="notice">${candidates.length} valid candidates · ${dupes} duplicates skipped · ${invalid} incomplete rows skipped</div><p class="muted" style="font-size:11px">${candidates.slice(0,5).map(l=>esc(l.name)+' · '+esc(l.city)).join('<br>')}</p>`;document.getElementById('import-confirm').disabled=!candidates.length}catch(err){document.getElementById('import-preview').textContent=err.message;document.getElementById('import-confirm').disabled=true}};document.getElementById('import-confirm').onclick=()=>{db.leads.push(...candidates);log('Candidates imported',candidates.length+' profiles added from CSV','upload');closeModal();render();toast(candidates.length+' candidates imported')}}
function simulate(){modal('Simulate a group message',`<form id="sim-form">${selectField('Group','group',db.groups.map(g=>g.name),db.groups.find(g=>g.id===selectedGroup)?.name)}${field('Sender','sender','Julien Morel')}${selectField('Message type','kind',['Text message','Voice note transcript'],'Text message')}<div class="field"><label for="sim-message">Message / demo transcript</label><textarea name="text" id="sim-message" required>Looking for 2 React developers in Paris. Full-time, available immediately. React and TypeScript experience.</textarea></div><div class="notice">${ic('mic')}Voice playback uses your browser’s speech synthesis for this demo.</div><button class="btn primary" type="submit">Add to demo inbox</button></form>`);document.getElementById('sim-form').onsubmit=e=>{e.preventDefault();const d=Object.fromEntries(new FormData(e.target)),g=db.groups.find(g=>g.name===d.group);db.messages.push({id:uid(),group:g.id,sender:d.sender,text:d.text,time:'Just now',kind:d.kind==='Voice note transcript'?'voice':'text',processed:false});selectedGroup=g.id;log('Group message received',g.name,'chat');closeModal();navigate('WhatsApp inbox');toast(g.active?'Message added · Review & capture its requirement.':'Message added · Capture is paused for this group.')}}
function extract(id){const m=db.messages.find(m=>m.id===id),g=db.groups.find(g=>g.id===m.group);if(!g.active)return toast('Resume capture for this group first.');const text=m.text;const city=['Paris','London','Lyon','Manchester','Berlin','Marseille'].find(c=>text.toLowerCase().includes(c.toLowerCase()))||'';const country=['London','Manchester'].includes(city)?'United Kingdom':city==='Berlin'?'Germany':g.country;const category=/nurs|health/i.test(text)?'Healthcare':/warehouse|logistic/i.test(text)?'Logistics':/hotel|hospitality/i.test(text)?'Hospitality':/design|figma/i.test(text)?'Design':g.category;const role=category==='Healthcare'?'Registered Nurse':category==='Technology'?'React Developer':category==='Logistics'?'Warehouse Associate':category==='Hospitality'?'Hotel Operations Manager':category==='Design'?'UI / UX Designer':'Customer Support Specialist';const skills=(text.match(/React|TypeScript|NMC|Nursing|Figma|French|Warehouse|Inventory/gi)||[category]).join(', ');requirementForm({role,city,country,category,count:+(text.match(/\b(\d+)\b/)||[])[1]||1,type:/contract/i.test(text)?'Contract':'Full-time',group:g.name,description:text,skills,source:m.kind==='voice'?'Voice note':'Text'},id)}
function sendOutreach(id){const o=db.outreach.find(o=>o.id===id);if(!o||o.status!=='Draft')return;const l=db.leads.find(l=>l.id===o.lead);if(!l||l.blocked||!l.consent||l.availability==='Unavailable'){o.status='Skipped';log('Outreach blocked','Contact is excluded, unavailable or has not opted in','shield');render();return toast('Skipped: this candidate is not eligible for outreach.')}o.status='Sent';o.time='Just now';const r=db.requirements.find(r=>r.id===o.req);if(r&&r.status!=='Filled')r.status='Outreach';log('Demo outreach sent',l.name+' · '+r?.role,'send');render();toast('Message sent in demo mode')}
function editOutreach(id){const o=db.outreach.find(o=>o.id===id);modal('Edit outreach draft',`<form id="outreach-form"><div class="field"><label for="draft-text">Message</label><textarea id="draft-text" name="text" required style="min-height:150px">${esc(o.text)}</textarea></div><button type="submit" class="btn primary">Save draft</button></form>`);document.getElementById('outreach-form').onsubmit=e=>{e.preventDefault();o.text=new FormData(e.target).get('text').trim();if(!o.text)return;log('Outreach draft edited',o.req,'send');closeModal();render();toast('Draft saved')}}
function bind(){document.querySelectorAll('[data-nav]').forEach(el=>el.onclick=e=>{e.preventDefault();navigate(el.dataset.nav)});document.querySelectorAll('[data-action]').forEach(el=>el.onclick=e=>{e.stopPropagation();action(el.dataset.action)});document.querySelectorAll('[data-detail]').forEach(el=>{el.onclick=()=>detail(el.dataset.detail);el.onkeydown=e=>{if(e.key==='Enter')detail(el.dataset.detail)}});document.querySelectorAll('[data-tab]').forEach(el=>el.onclick=()=>{reqTab=el.dataset.tab;render()});document.querySelectorAll('[data-group]').forEach(el=>el.onclick=()=>{selectedGroup=el.dataset.group;navigate('WhatsApp inbox')});document.querySelectorAll('[data-outreach-tab]').forEach(el=>el.onclick=()=>{statusFilter=el.dataset.outreachTab;render()});const search=document.getElementById('filter');if(search)search.oninput=e=>{let pos=e.target.selectionStart;filter=e.target.value;render();const input=document.getElementById('filter');input.focus();input.setSelectionRange(pos,pos)};for(const [id,setter] of [['country-filter',v=>countryFilter=v],['category-filter',v=>categoryFilter=v],['status-filter',v=>statusFilter=v]]){const el=document.getElementById(id);if(el)el.onchange=e=>{setter(e.target.value);render()}}document.getElementById('global-search').onkeydown=e=>{if(e.key==='Enter'){globalQuery=e.target.value.trim();render()}};const form=document.getElementById('chat-form');if(form)form.onsubmit=e=>{e.preventDefault();const text=new FormData(e.target).get('message').trim();if(!text)return;db.messages.push({id:uid(),group:selectedGroup,sender:'You',text,time:'Just now',kind:'text',processed:false});log('Demo group reply sent',db.groups.find(g=>g.id===selectedGroup).name,'send');render()};const sf=document.getElementById('settings-form');if(sf)sf.onsubmit=e=>{e.preventDefault();db.settings.workspace=new FormData(e.target).get('workspace').trim();save();render();toast('Workspace updated')}}
function bindModal(){document.querySelectorAll('#modal-root [data-action]').forEach(el=>el.onclick=()=>action(el.dataset.action));const overlay=document.querySelector('.overlay');if(overlay)overlay.onclick=e=>{if(e.target===overlay)closeModal()}}
function action(a){const [cmd,id]=a.split(':');switch(cmd){case 'menu':document.querySelector('.sidebar').classList.toggle('open');break;case 'close':closeModal();break;case 'new-req':requirementForm();break;case 'detail':detail(id);break;case 'edit-req':requirementForm(db.requirements.find(r=>r.id===id));break;case 'save-status':{const r=db.requirements.find(r=>r.id===id);r.status=document.getElementById('req-state').value;log('Requirement status updated',r.id+' → '+r.status,'brief');closeModal();render();toast('Status updated');break}case 'match':{const result=runEngine(id);closeModal();navigate('Outreach');toast(`${result.drafts} drafts created · ${result.skips} skipped`);break}case 'run-engine':{const result=runEngine();render();toast(`${result.drafts} ${db.settings.review?'drafts created':'simulated sends'} · ${result.skips} skipped`);break}case 'new-lead':leadForm();break;case 'edit-lead':leadForm(id);break;case 'import':importModal();break;case 'sample-csv':download('verdant-leads-template.csv','name,city,country,category,skills,email,phone,availability,consent\nTaylor Demo,Paris,France,Technology,"React, TypeScript",taylor@example.com,,Available,false');break;case 'export-leads':{const keys=['name','city','country','category','skills','email','phone','availability','consent'];download('verdant-candidates.csv',keys.join(',')+'\n'+filtered(db.leads).map(l=>keys.map(k=>csvCell(l[k])).join(',')).join('\n'));toast('Candidates exported');break}case 'simulate':simulate();break;case 'extract':extract(id);break;case 'toggle-group':{const g=db.groups.find(g=>g.id===id);g.active=!g.active;log(g.active?'Group capture resumed':'Group capture paused',g.name,'chat');render();break}case 'voice':{const m=db.messages.find(m=>m.id===id);if(!('speechSynthesis' in window))return toast('Speech playback is unavailable in this browser. Transcript is shown.');speechSynthesis.cancel();const u=new SpeechSynthesisUtterance(m.text);u.lang='en-GB';u.rate=.95;speechSynthesis.speak(u);toast('Playing demo voice transcript');break}case 'send':sendOutreach(id);break;case 'skip':{const o=db.outreach.find(o=>o.id===id);o.status='Skipped';log('Outreach skipped',o.req,'send');render();toast('Candidate skipped for this requirement');break}case 'reply':{const o=db.outreach.find(o=>o.id===id);o.status='Replied';const l=db.leads.find(l=>l.id===o.lead);log('Candidate replied',l.name+' · Interested in this opportunity','chat');if(!db.tasks.some(t=>t.title==='Follow up with '+l.name))db.tasks.unshift({id:uid(),title:'Follow up with '+l.name,req:o.req,description:'Candidate is interested. Review availability and arrange a conversation.',status:'To do',owner:'Alex Morgan',due:'Today'});save();render();toast('Demo reply received · Follow-up task created');break}case 'edit-outreach':editOutreach(id);break;case 'new-task':taskForm();break;case 'edit-task':taskForm(id);break;case 'move-task':{const t=db.tasks.find(t=>t.id===id);t.status=t.status==='To do'?'In progress':t.status==='In progress'?'Done':'To do';log('Task moved',t.title+' → '+t.status,'tasks');render();break}case 'switch':db.settings[id]=!db.settings[id];log('Automation preference changed',id+' → '+db.settings[id],'settings');render();break;case 'save-settings':document.getElementById('settings-form').requestSubmit();break;case 'notifications':modal('Workspace activity',`<div class="activity">${db.activity.map(a=>`<div class="event"><span class="event-icon">${ic(a.type)}</span><div><strong>${esc(a.title)}</strong><p>${esc(a.detail)}</p><small>${esc(a.time)}</small></div></div>`).join('')}</div>`);break;case 'guide':modal('Welcome to a calmer workflow',`<p class="muted" style="line-height:1.9">Start in WhatsApp inbox and simulate a message. Review & capture its requirement, inspect the matched people, and create outreach drafts. Approve a draft to simulate sending. Candidate replies create shared follow-up tasks.</p><div class="notice" style="margin-top:20px">${ic('shield')}Everything here is a frontend demo. No real messages are sent.</div>`,btn('Explore inbox','go-inbox',true,'arrow'));break;case 'go-inbox':closeModal();navigate('WhatsApp inbox');break;case 'clear-search':globalQuery='';render();break;case 'export-report':download('verdant-report.csv','metric,value\nRequirements,'+db.requirements.length+'\nCandidates,'+db.leads.length+'\nDrafts,'+db.outreach.filter(o=>o.status==='Draft').length+'\nMessages sent,'+db.outreach.filter(o=>['Sent','Replied'].includes(o.status)).length+'\nReplies,'+db.outreach.filter(o=>o.status==='Replied').length);toast('Report exported');break;case 'backup':download('verdant-backup.json',JSON.stringify(db,null,2),'application/json');break;case 'restore':restore();break;case 'reset':modal('Reset this demo workspace?',`<p class="muted" style="font-size:12px;line-height:1.9">This replaces your browser’s current data with the original demo. Export a backup first to preserve your changes.</p>`,btn('Cancel','close')+btn('Reset demo','confirm-reset',true,'refresh'));break;case 'confirm-reset':db=seed();save();closeModal();navigate('Overview');toast('Original demo restored');break}}
function restore(){modal('Restore a workspace backup','<div class="upload-box"><p>Choose a Verdant JSON backup. Your current browser data will be replaced after confirmation.</p><input type="file" id="restore-file" accept=".json,application/json"></div><div id="restore-info" class="field-error" style="margin-top:18px"></div>',btn('Cancel','close')+'<button class="btn primary" id="restore-confirm" disabled>Replace workspace data</button>');let incoming;document.getElementById('restore-file').onchange=async e=>{try{const f=e.target.files[0];if(!f)return;if(f.size>5*1024*1024)throw Error('Backup must be smaller than 5 MB.');incoming=JSON.parse(await f.text());const keys=['requirements','leads','groups','messages','outreach','tasks','activity'];if(incoming.version!==1||!incoming.settings||keys.some(k=>!Array.isArray(incoming[k])))throw Error('This is not a supported Verdant backup.');for(const r of incoming.requirements)if(!r.id||!r.role||!r.skills||!r.country||!r.city)throw Error('Invalid requirement in backup.');for(const l of incoming.leads)if(!l.id||!l.name||!l.skills||!l.country)throw Error('Invalid candidate in backup.');if(!incoming.groups.length)throw Error('Backup must include at least one group.');document.getElementById('restore-info').textContent=incoming.leads.length+' candidates and '+incoming.requirements.length+' requirements ready to restore.';document.getElementById('restore-confirm').disabled=false}catch(err){incoming=null;document.getElementById('restore-info').textContent=err.message;document.getElementById('restore-confirm').disabled=true}};document.getElementById('restore-confirm').onclick=()=>{db=incoming;save();selectedGroup=db.groups[0].id;closeModal();navigate('Overview');toast('Workspace restored')}}
document.addEventListener('keydown',e=>{if(e.key==='Escape')closeModal();if(e.key==='Tab'&&document.querySelector('.modal')){const items=[...document.querySelectorAll('.modal button:not(:disabled),.modal input,.modal select,.modal textarea')];if(e.shiftKey&&document.activeElement===items[0]){e.preventDefault();items.at(-1).focus()}else if(!e.shiftKey&&document.activeElement===items.at(-1)){e.preventDefault();items[0].focus()}}});
save();render();
